"""A splittable spend allowance: the bound the delegation call signature carries.

A per-process cap cannot bound a tree whose width the model chooses at run time.
An allowance can, because splitting is subtraction: total spend anywhere in the
tree is bounded by the root grant however wide or deep the tree turns out to be.
A fan-out that would starve its own children is refused here, at the spawn site,
rather than discovered later on an invoice.
"""


class AllowanceExceeded(Exception):
    """Raised at the call site INSTEAD of making the request."""


MIN_VIABLE_USD = 0.05


class Allowance:
    def __init__(self, remaining_usd: float) -> None:
        self.remaining_usd = remaining_usd

    def charge(self, usd: float) -> None:
        if usd > self.remaining_usd:
            raise AllowanceExceeded(f"grant of {self.remaining_usd} is exhausted")
        self.remaining_usd -= usd

    def split(self, n: int) -> list["Allowance"]:
        """Carve one share per child out of THIS grant, never out of thin air."""
        if n <= 0:
            return []
        share = self.remaining_usd / (n + 1)
        if share < MIN_VIABLE_USD:
            raise AllowanceExceeded(
                f"fan-out of {n} would leave {share} per child, below the floor"
            )
        self.remaining_usd -= share * n
        return [Allowance(share) for _ in range(n)]
